// Des: Extract visible text and title from HTML
// Flo: walk bytes > skip comments and script/style blocks > drop tags (block tags = newline) > decode entities > collapse spaces
// I/O: HTML bytes (UTF-8) > owned text / owned title (caller frees)
// ===================================================================
const std = @import("std"); const mem2 = std.mem;
const CF = .{ .skip = @as([]const []const u8, &.{ "script", "style", "noscript", "svg", "template", "head" }), .blok = @as([]const []const u8, &.{ "br", "p", "div", "li", "tr", "h1", "h2", "h3", "h4", "h5", "h6", "section", "article", "ul", "ol", "table", "hr", "header", "footer" }), .name = @as([]const []const u8, &.{ "amp", "lt", "gt", "quot", "apos", "nbsp", "ndash", "mdash", "hellip", "copy" }), .nval = @as([]const []const u8, &.{ "&", "<", ">", "\"", "'", " ", "\xE2\x80\x93", "\xE2\x80\x94", "\xE2\x80\xA6", "\xC2\xA9" }) };
fn inzzLisz(list: []const []const u8, name: []const u8) bool { for (list) |item| if (std.ascii.eqlIgnoreCase(item, name)) return true; return false; }
fn tagzEndz(html: []const u8, from: usize) usize { var indx = from; var quot: u8 = 0; while (indx < html.len) : (indx += 1) { const byte = html[indx]; if (quot != 0) { if (byte == quot) quot = 0; } else if (byte == '"' or byte == '\'') { quot = byte; } else if (byte == '>') return indx + 1; } return html.len; }
fn entiDeco(allo: std.mem.Allocator, outp: *std.ArrayList(u8), html: []const u8, from: usize) !usize { const semi = mem2.findScalarPos(u8, html, from + 1, ';') orelse return 0; if (semi - from > 10) return 0; const name = html[from + 1 .. semi]; if (name.len > 1 and name[0] == '#') { const code = (if (name[1] == 'x' or name[1] == 'X') std.fmt.parseInt(u21, name[2..], 16) else std.fmt.parseInt(u21, name[1..], 10)) catch return 0; var buff: [4]u8 = undefined; const lenz = std.unicode.utf8Encode(code, &buff) catch return 0; try outp.appendSlice(allo, buff[0..lenz]); return semi + 1 - from; } for (CF.name, 0..) |item, indx| { if (mem2.eql(u8, item, name)) { try outp.appendSlice(allo, CF.nval[indx]); return semi + 1 - from; } } return 0; }
pub fn htmlText(allo: std.mem.Allocator, html: []const u8) ![]u8 { var outp: std.ArrayList(u8) = .empty; errdefer outp.deinit(allo); var indx: usize = 0; var gapz = false; var newl = false; while (indx < html.len) { const byte = html[indx]; if (byte == '<' and indx + 1 < html.len and (std.ascii.isAlphabetic(html[indx + 1]) or html[indx + 1] == '/' or html[indx + 1] == '!' or html[indx + 1] == '?')) { if (mem2.startsWith(u8, html[indx..], "<!--")) { const endz = mem2.find(u8, html[indx..], "-->"); indx = if (endz) |ezzz| indx + ezzz + 3 else html.len; continue; } var nend = indx + 1; if (nend < html.len and html[nend] == '/') nend += 1; const nbeg = nend; while (nend < html.len and (std.ascii.isAlphanumeric(html[nend]))) nend += 1; const name = html[nbeg..nend]; const clo2 = indx + 1 < html.len and html[indx + 1] == '/'; const afte = tagzEndz(html, nend); if (!clo2 and inzzLisz(CF.skip, name)) { var scan = afte; while (scan < html.len) { const clzz = mem2.findPos(u8, html, scan, "</") orelse { scan = html.len; break; }; var cezz = clzz + 2; const cbzz = cezz; while (cezz < html.len and std.ascii.isAlphanumeric(html[cezz])) cezz += 1; if (std.ascii.eqlIgnoreCase(html[cbzz..cezz], name)) { scan = tagzEndz(html, cezz); break; } scan = clzz + 2; } indx = scan; continue; } if (name.len > 0 and inzzLisz(CF.blok, name)) newl = true else gapz = true; indx = afte; continue; } if (std.ascii.isWhitespace(byte)) { gapz = true; indx += 1; continue; } if (outp.items.len > 0 and (newl or gapz)) { try outp.append(allo, if (newl) '\n' else ' '); } newl = false; gapz = false; if (byte == '&') { const used = try entiDeco(allo, &outp, html, indx); if (used > 0) { indx += used; continue; } } try outp.append(allo, byte); indx += 1; } return outp.toOwnedSlice(allo); }
pub fn htmlTitl(allo: std.mem.Allocator, html: []const u8) !?[]u8 { var begz: ?usize = null; var indx: usize = 0; while (mem2.findPos(u8, html, indx, "<")) |ltzz| { if (ltzz + 6 <= html.len and std.ascii.eqlIgnoreCase(html[ltzz .. ltzz + 6], "<title")) { begz = tagzEndz(html, ltzz + 6); break; } indx = ltzz + 1; } const stz2 = begz orelse return null; var endz = stz2; while (mem2.findPos(u8, html, endz, "<")) |ltzz| { if (ltzz + 7 <= html.len and std.ascii.eqlIgnoreCase(html[ltzz .. ltzz + 7], "</title")) { const frag = html[stz2..ltzz]; const text = try htmlText(allo, frag); return text; } endz = ltzz + 1; } return null; }
